import re

_POSITIVE_INT = re.compile(r"[0-9]+")


def _positive_int(value, default):
    if value is None:
        return default
    # int() alone would accept " 5", "+5", "1_0" and non-ASCII digits.
    if not isinstance(value, str) or not _POSITIVE_INT.fullmatch(value):
        raise ValueError(f"invalid positive integer: {value!r}")
    n = int(value)
    if n < 1:
        raise ValueError(f"must be >= 1: {value!r}")
    return n


def parse_pagination(params):
